  function box(type,fn){ var c1={x:0,y:0,r:15,type:type,loot:[],opened:false,time:1,best:'common',prog:0}, c2; if(fn) fn(c1); c2={}; for(var q in c1) c2[q]=c1[q]; c2.opened=true; items.push(['c',c1],['c',c2]); }
